import argparse
import csv
import sys

from ledger.export import export_csv


def main(argv=None):
    parser = argparse.ArgumentParser(prog="ledger")
    commands = parser.add_subparsers(dest="command", required=True)
    export = commands.add_parser("export")
    export.add_argument("--out", required=True)
    export.add_argument("--append", action="store_true", help="append to --out instead of replacing it")
    args = parser.parse_args(argv)
    with open(args.out, "a" if args.append else "w", newline="") as out:
        export_csv(csv.reader(sys.stdin), out)
